/**
 * Admin Dashboard Legacy
 * Original admin dashboard view with overview statistics
 */

import React, { useState, useEffect } from 'react';
import LoadingSpinner from '../components/LoadingSpinner';
import axios from 'axios';
import './AdminDashboard.css';

const AdminDashboardLegacy = () => {
  const [dashboard, setDashboard] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [refreshing, setRefreshing] = useState(false);

  const token = localStorage.getItem('token');

  useEffect(() => {
    fetchDashboard();
  }, []);

  const fetchDashboard = async () => {
    try {
      // Try the new analytics endpoint first, fallback to old dashboard endpoint
      const response = await axios.get('http://localhost:5000/api/admin/analytics', {
        headers: { Authorization: `Bearer ${token}` },
      });
      
      if (response.data?.data) {
        setDashboard(response.data.data);
        setError('');
      }
    } catch (err) {
      const errorMsg = err.response?.data?.message || err.message || 'Failed to fetch dashboard';
      setError(errorMsg);
      console.error('Dashboard fetch error:', err);
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  const handleRefresh = async () => {
    setRefreshing(true);
    await fetchDashboard();
  };

  if (loading) {
    return <LoadingSpinner message="Loading admin dashboard..." />;
  }

  if (error && !dashboard) {
    return (
      <div className="admin-dashboard-page">
        <div className="admin-container">
          <div className="error-container">
            <h2>⚠️ Error Loading Dashboard</h2>
            <p>{error}</p>
            <button className="refresh-btn" onClick={handleRefresh}>
              🔄 Retry
            </button>
          </div>
        </div>
      </div>
    );
  }

  const { summary = {}, monthlyRevenue = [], bookingTrends = [], popularEvents = [], topUsers = [] } = dashboard || {};

  return (
    <div className="admin-dashboard-page">
      <div className="admin-container">
        <div className="dashboard-header">
          <div className="header-title">
            <div className="logo-box-header">
              <svg className="header-logo-svg" viewBox="0 0 40 40" xmlns="http://www.w3.org/2000/svg">
                <g fill="white">
                  <rect x="6" y="8" width="28" height="24" fill="none" stroke="white" strokeWidth="2" rx="2"/>
                  <line x1="12" y1="8" x2="12" y2="4" strokeWidth="2" strokeLinecap="round"/>
                  <line x1="28" y1="8" x2="28" y2="4" strokeWidth="2" strokeLinecap="round"/>
                  <line x1="6" y1="16" x2="34" y2="16" strokeWidth="1.5"/>
                  <circle cx="16" cy="24" r="2" fill="white"/>
                  <circle cx="24" cy="24" r="2" fill="white"/>
                </g>
              </svg>
            </div>
            <h1>Dashboard Overview</h1>
          </div>
          <button 
            className="refresh-btn" 
            onClick={handleRefresh}
            disabled={refreshing}
          >
            🔄 {refreshing ? 'Refreshing...' : 'Refresh'}
          </button>
        </div>

        {/* Stats Grid */}
        <div className="stats-grid">
          <div className="stat-card">
            <span className="stat-icon">👥</span>
            <div className="stat-content">
              <h3>Total Users</h3>
              <p className="stat-value">{Math.max(0, summary?.totalUsers || 0)}</p>
            </div>
          </div>

          <div className="stat-card">
            <span className="stat-icon">🎫</span>
            <div className="stat-content">
              <h3>Total Bookings</h3>
              <p className="stat-value">{Math.max(0, summary?.totalBookings || 0)}</p>
            </div>
          </div>

          <div className="stat-card">
            <span className="stat-icon">💰</span>
            <div className="stat-content">
              <h3>Total Revenue</h3>
              <p className="stat-value revenue">${Math.max(0, summary?.totalRevenue || 0).toFixed(2)}</p>
            </div>
          </div>
        </div>

        {/* Top Events */}
        {popularEvents && popularEvents.length > 0 && (
          <div className="recent-activity-section">
            <h2>⭐ Top Events</h2>
            <div className="table-container">
              <table className="data-table">
                <thead>
                  <tr>
                    <th>Event Name</th>
                    <th>Total Bookings</th>
                    <th>Status</th>
                  </tr>
                </thead>
                <tbody>
                  {popularEvents.slice(0, 10).map((event, idx) => (
                    <tr key={event._id} className={idx === 0 ? 'top-highlight' : ''}>
                      <td className="event-name-cell">
                        {idx === 0 && '🏆 '}
                        <span className="event-name">{event.title}</span>
                      </td>
                      <td className="bookings-cell">
                        <span className="bookings-badge">{event.bookingCount}</span>
                      </td>
                      <td className="status-cell">
                        <span className={`status-badge ${event.bookingCount > 50 ? 'sold-out' : 'active'}`}>
                          {event.bookingCount > 50 ? 'Popular' : 'Active'}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* Top Users */}
        {topUsers && topUsers.length > 0 && (
          <div className="recent-activity-section">
            <h2>👑 Top Users</h2>
            <div className="table-container">
              <table className="data-table">
                <thead>
                  <tr>
                    <th>User Name</th>
                    <th>Total Bookings</th>
                    <th>Total Spent</th>
                  </tr>
                </thead>
                <tbody>
                  {topUsers.slice(0, 10).map((user, idx) => (
                    <tr key={user._id} className={idx === 0 ? 'top-highlight' : ''}>
                      <td className="user-cell">
                        {idx === 0 && '🏆 '}
                        <span className="user-name">{user.name}</span>
                      </td>
                      <td className="bookings-cell">
                        <span className="bookings-badge">{user.bookingCount}</span>
                      </td>
                      <td className="revenue-cell">${user.totalSpent.toFixed(2)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default AdminDashboardLegacy;
